import{useEffect,useState}from'react';import type{RouteConfig}from'@mercurjs/dashboard-sdk';declare const __BACKEND_URL__:string;export const config:RouteConfig={label:'بيانات المتجر',rank:70};const api=async(p:string,i?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${p}`,{credentials:'include',...i,headers:{...(i?.body?{'content-type':'application/json'}:{}),...(i?.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||`HTTP ${r.status}`);return d};export default function P(){const[f,setF]=useState<any>({phone:'',address:'',city:'',governorate:'',latitude:'',longitude:'',google_maps_url:''}),[m,setM]=useState('');useEffect(()=>{api('/vendor/spike/store-profile').then(d=>setF({...f,...(d.profile||{})})).catch(e=>setM(e.message))},[]);const save=async()=>{try{await api('/vendor/spike/store-profile',{method:'POST',body:JSON.stringify(f)});setM('تم حفظ بيانات وموقع المتجر')}catch(e:any){setM(e.message)}};return <div dir="rtl" style={{padding:24,maxWidth:800}}><h1>بيانات المتجر</h1><p>موقع المتجر يستخدم لحساب مسافة الشحن داخل المدينة.</p>{m&&<p>{m}</p>}<div style={{display:'grid',gap:10}}><input placeholder="رقم التواصل" value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/><input placeholder="المحافظة" value={f.governorate} onChange={e=>setF({...f,governorate:e.target.value})}/><input placeholder="المدينة" value={f.city} onChange={e=>setF({...f,city:e.target.value})}/><input placeholder="العنوان" value={f.address} onChange={e=>setF({...f,address:e.target.value})}/><input placeholder="رابط Google Maps" value={f.google_maps_url} onChange={e=>setF({...f,google_maps_url:e.target.value})}/><div style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:8}}><input type="number" step="any" placeholder="Latitude" value={f.latitude} onChange={e=>setF({...f,latitude:e.target.value})}/><input type="number" step="any" placeholder="Longitude" value={f.longitude} onChange={e=>setF({...f,longitude:e.target.value})}/></div><button onClick={save}>حفظ</button></div></div>}
